<script setup lang="ts">import{ref}from"vue";import{useRouter,useRoute}from"vue-router";import{useAuth}from"../auth";import{ApiError}from"../api";const username=ref("");const password=ref("");const error=ref(useRoute().query.error?"需要管理员权限":"");const busy=ref(false);const auth=useAuth();const router=useRouter();async function submit(){busy.value=true;error.value="";try{await auth.login(username.value,password.value);if(!auth.user?.admin){auth.logout();error.value="需要管理员权限";return}await router.replace("/")}catch(e){error.value=e instanceof ApiError&&e.code==="invalid_credentials"?"用户名或密码错误":"登录失败或会话已过期"}finally{busy.value=false}}</script>
<template><main class="login"><el-card><h1>KWiki 管理后台</h1><p>索引版本与发布控制</p><el-alert v-if="error" :title="error" type="error"/><el-form @submit.prevent="submit"><el-form-item label="用户名"><el-input v-model="username" autocomplete="username"/></el-form-item><el-form-item label="密码"><el-input v-model="password" type="password" autocomplete="current-password"/></el-form-item><el-button native-type="submit" type="primary" :loading="busy">登录</el-button></el-form></el-card></main></template>
